from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    r0, r1 = min(r for r, c in zeros), max(r for r, c in zeros)
    c0, c1 = min(c for r, c in zeros), max(c for r, c in zeros)
    bh, bw = r1 - r0 + 1, c1 - c0 + 1

    def cells(top, left):
        return [(r, c) for r in range(top, top + bh)
                       for c in range(left, left + bw)]

    start = (r0, c0)
    q = deque([start])
    dist = {start: 0}

    while q:
        top, left = q.popleft()
        for dt, dl in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nt, nl = top + dt, left + dl
            if (nt, nl) in dist or nt < 0 or nl < 0 or nt + bh > h or nl + bw > w:
                continue
            if all(grid[r][c] in (0, 1, 2) for r, c in cells(nt, nl)):
                dist[(nt, nl)] = dist[(top, left)] + 1
                q.append((nt, nl))

    targets2 = [(pos, d) for pos, d in dist.items()
                if pos != start and all(grid[r][c] == 2 for r, c in cells(*pos))]
    if targets2:
        target = max(targets2, key=lambda x: x[1])[0]
    else:
        targets1 = [(pos, d) for pos, d in dist.items()
                    if pos != start and all(grid[r][c] == 1 for r, c in cells(*pos))]
        target = max(targets1, key=lambda x: x[1])[0] if targets1 else start

    out = [row[:] for row in grid]
    for r, c in zeros:
        out[r][c] = 1
    if target != start:
        for r, c in cells(*target):
            out[r][c] = 0
    return out
